 "content": "def transform(grid):
    """Recolor complete separator rows/columns from the foreground line color to 2."""
    h, w = len(grid), len(grid[0])
    # The non-background color making up the long, complete lines is the
    # second-most common color (the background is dominant in these puzzles).
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    line_color = min(counts, key=lambda value: (-counts[value], value))
    # ARC instances may use a background color with many scattered pixels;
    # a full row or column of another color is the separator.
    full_rows = {r for r in range(h) if all(v == line_color for v in grid[r])}
    full_cols = {c for c in range(w) if all(grid[r][c] == line_color for r in range(h))}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if (r in full_rows or c in full_cols) and grid[r][c] == line_color:
                out[r][c] = 2
    return out

if __name__ == "__main__":
    test = [
        [5,5,5,5,8,5,5,5,5,5], [8,5,5,5,8,5,8,5,5,5], [8,8,8,8,8,8,8,8,8,8],
        [5,5,5,5,8,5,5,5,5,5], [5,5,5,5,8,5,5,5,5,5], [5,5,5,5,8,5,5,5,8,8],
        [5,5,5,5,8,5,5,5,5,5], [5,5,8,8,8,5,5,8,5,5], [5,5,5,5,8,5,5,5,5,5],
        [8,8,8,8,8,8,8,8,8,8], [5,5,5,5,8,5,5,5,5,5], [5,8,5,5,8,5,8,5,5,5],
        [5,5,5,5,8,5,5,5,5,5], [5,8,5,5,8,5,5,5,5,5], [8,8,8,8,8,8,8,8,8,8],
        [8,8,8,8,8,8,8,8,8,8], [5,5,5,5,8,5,5,5,5,5], [5,5,5,5,8,5,5,8,5,5],
        [8,8,8,8,8,8,8,8,8,8], [5,5,5,8,8,5,5,5,5,5],
    ]
    for row in transform(test):
        print(*row)
    assert all(all(v == 2 for v in transform(test)[r]) for r in [2,9,14,15,18])
    assert all(transform(test)[r][4] == 2 for r in range(20))
    print('test transformation verified')
